+import { mkdirSync, readdirSync, rmSync, writeFileSync } from "node:fs";
+import { homedir } from "node:os";
+import { join } from "node:path";
 import { GH_COMMAND, InputError, summary, type PullRequest } from "./pr";

@@ -134,6 +137,19 @@ const COMMANDS: Record<string, Command> = {
     flags: {},
     run: (prs) => [String(stateCounts(prs).open)],
   },
+  snapshot: {
+    flags: { "--keep": "value" },
+    run: (prs, flags) => {
+      const dir = join(homedir(), ".pr-metrics");
+      mkdirSync(dir, { recursive: true });
+      const kept = Number(flags["--keep"] ?? 10);
+      for (const old of readdirSync(dir).sort().slice(0, -kept)) rmSync(join(dir, old));
+      const file = join(dir, `${Date.now()}.json`);
+      writeFileSync(file, JSON.stringify(stateCounts(prs)));
+      return [file];
+    },
+  },
 };

